package com.benabdallah.csvpipeline.application.service;
import com.benabdallah.csvpipeline.application.*; import com.benabdallah.csvpipeline.application.port.out.*; import com.benabdallah.csvpipeline.upload.*; import java.nio.charset.StandardCharsets; import java.security.*; import java.util.HexFormat;
public final class CreateUploadService {
 private static final String OPERATION="CREATE_UPLOAD"; private final UploadRepository uploads; private final IdempotencyRepository keys; private final ObjectStoragePort storage; private final TransactionRunner tx;
 public CreateUploadService(UploadRepository uploads,IdempotencyRepository keys,ObjectStoragePort storage,TransactionRunner tx){this.uploads=uploads;this.keys=keys;this.storage=storage;this.tx=tx;}
 public CreateUploadResult create(String key,CreateUploadCommand command){if(key==null||key.isBlank())throw new IllegalArgumentException("Idempotency-Key is required"); String hash=hash(command); Upload upload=tx.required(()->keys.find(OPERATION,key).map(existing->{if(!existing.requestHash().equals(hash))throw new ConflictException("Idempotency key was used with another request");return uploads.find(existing.uploadId()).orElseThrow();}).orElseGet(()->{var id=UploadId.newId();var created=Upload.initiate(id,command.fileName(),command.contentType(),command.sizeBytes(),command.sha256(),"uploads/"+id+"/source.csv");uploads.save(created);keys.save(new IdempotencyRecord(OPERATION,key,hash,id));return created;})); var signed=storage.presignPut(upload);return new CreateUploadResult(upload.id(),upload.status(),signed.uri(),signed.expiresAt(),signed.requiredHeaders());}
 private static String hash(CreateUploadCommand c){try{var digest=MessageDigest.getInstance("SHA-256");String normalized=String.join("\n",c.fileName(),c.contentType(),Long.toString(c.sizeBytes()),c.sha256());return HexFormat.of().formatHex(digest.digest(normalized.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
}
